<?php

namespace App\Services;

/** Editable HTML drafts of the sec 4(1), 7(1) and 8(3) notices (replace by the official Schedule forms when available). */
class NoticeTemplates
{
    public static function render(string $type, array $c): string
    {
        $rows = '';
        foreach ($c['lands'] ?? [] as $i => $l) {
            $rows .= '<tr><td>' . ($i + 1) . "</td><td>{$l['upazila']}</td><td>{$l['mouza']}</td><td>{$l['jl']}</td><td>{$l['khatian']}</td><td>{$l['dag']}</td><td>{$l['area']}</td></tr>";
        }
        $table = '<table border="1" cellpadding="4" cellspacing="0" width="100%"><tr><th>ক্রম</th><th>উপজেলা</th><th>মৌজা</th><th>জেএল</th><th>খতিয়ান</th><th>দাগ</th><th>অধিগ্রহণের পরিমাণ (একর)</th></tr>' . $rows . '</table>';
        $head = "<h3 style=\"text-align:center\">গণপ্রজাতন্ত্রী বাংলাদেশ সরকার<br>জেলা প্রশাসকের কার্যালয়, {$c['district']}</h3><p>এল.এ কেস নং: <b>{$c['la_case_no']}</b> &nbsp; তারিখ: {$c['date']}</p>";
        return match ($type) {
            '4_1' => $head . "<h4 style=\"text-align:center\">স্থাবর সম্পত্তি অধিগ্রহণ ও হুকুমদখল আইন, ২০১৭ এর ধারা ৪(১) অনুযায়ী প্রাথমিক নোটিশ</h4>
<p>এতদ্বারা সর্বসাধারণের অবগতির জন্য জানানো যাইতেছে যে, জনপ্রয়োজনে/জনস্বার্থে <b>{$c['project']}</b> বাস্তবায়নের লক্ষ্যে প্রত্যাশী সংস্থা <b>{$c['body']}</b> এর অনুকূলে নিম্নতফসিলে বর্ণিত ভূমি অধিগ্রহণের প্রস্তাব করা হইয়াছে।</p>$table
<p>এই নোটিশ জারির তারিখ হইতে <b>১৫ (পনের) কার্যদিবসের</b> মধ্যে (ধারা ৫(১)) অধিগ্রহণের বিরুদ্ধে কোনো স্বার্থসংশ্লিষ্ট ব্যক্তির আপত্তি থাকিলে তিনি নিম্নস্বাক্ষরকারীর নিকট লিখিতভাবে/অনলাইনে আপত্তি দাখিল করিতে পারিবেন।</p><p style=\"text-align:right\">জেলা প্রশাসক<br>{$c['district']}</p>",
            '7_1' => $head . "<h4 style=\"text-align:center\">স্থাবর সম্পত্তি অধিগ্রহণ ও হুকুমদখল আইন, ২০১৭ এর ধারা ৭(১) অনুযায়ী নোটিশ</h4>
<p>এতদ্বারা জানানো যাইতেছে যে, <b>{$c['project']}</b> এর জন্য নিম্নতফসিলের ভূমি অধিগ্রহণের সিদ্ধান্ত গৃহীত হইয়াছে এবং উক্ত ভূমির দখল গ্রহণের অভিপ্রায় ব্যক্ত করা হইল।</p>$table
<p>উক্ত ভূমিতে স্বার্থসংশ্লিষ্ট ব্যক্তিগণ নোটিশ জারির <b>১৫ (পনের) কার্যদিবস</b> (জাতীয় গুরুত্বপূর্ণ প্রকল্পে ৭ কার্যদিবস) পর নির্ধারিত সময় ও স্থানে হাজির হইয়া স্বত্বের অংশ ও দাবিকৃত ক্ষতিপূরণের পরিমাণ উল্লেখপূর্বক লিখিত দাবি দাখিল করিবেন (ধারা ৭(২))। মিথ্যা বিবরণ দাখিল দণ্ডবিধির ১৭৫ ও ১৭৬ ধারা অনুযায়ী দণ্ডনীয়।</p><p style=\"text-align:right\">জেলা প্রশাসক<br>{$c['district']}</p>",
            '8_3' => $head . "<h4 style=\"text-align:center\">স্থাবর সম্পত্তি অধিগ্রহণ ও হুকুমদখল আইন, ২০১৭ এর ধারা ৮(৩) অনুযায়ী রোয়েদাদের নোটিশ</h4>
<p>এতদ্বারা জানানো যাইতেছে যে, <b>{$c['project']}</b> এর অধিগ্রহণকৃত ভূমির ক্ষতিপূরণের রোয়েদাদ অনুমোদিত হইয়াছে। প্রত্যাশী সংস্থা কর্তৃক ক্ষতিপূরণের অর্থ জমা প্রদান করা হইয়াছে। স্বার্থসংশ্লিষ্ট ব্যক্তিগণ <b>" . ($c['distribution_date'] ?? '') . "</b> তারিখে <b>" . ($c['place'] ?? '') . "</b> স্থানে উপস্থিত হইয়া পরিচয়পত্রসহ ক্ষতিপূরণ গ্রহণ করিতে পারিবেন।</p>$table
<p>রোয়েদাদের পরিমাণে অসন্তুষ্ট ব্যক্তি নোটিশ জারির ৪৫ কার্যদিবসের মধ্যে আর্বিট্রেটরের নিকট আবেদন করিতে পারিবেন (ধারা ৩০)।</p><p style=\"text-align:right\">জেলা প্রশাসক<br>{$c['district']}</p>",
            default => $head,
        };
    }
}
